527: 
528:   // food
529:   for (const f of foods) {
530:     const sx = screenX(f.x), sy = screenY(f.y);
531:     if (sx < -20 || sx > width + 20 || sy < -20 || sy > height + 20) continue;
532:     ctx.fillStyle = f.color;
533:     ctx.beginPath();
534:     ctx.arc(sx, sy, 3.2, 0, Math.PI * 2);
535:     ctx.fill();
536:   }
537: 
538:   // creatures
539:   for (const c of creatures) {
540:     const sx = screenX(c.x), sy = screenY(c.y);
541:     if (sx < -60 || sx > width + 60 || sy < -60 || sy > height + 60) continue;
542:     const d = c.dna;
543:     const r = d.size;
544:     const energyPct = Math.max(0, Math.min(1, c.energy / 100));
545:     ctx.globalAlpha = 0.42 + 0.58 * energyPct;
546:     ctx.fillStyle = `hsl(${d.hue}, 72%, 56%)`;
547:     ctx.beginPath();
548:     ctx.arc(sx, sy, r, 0, Math.PI * 2);
549:     ctx.fill();
550:     ctx.strokeStyle = 'rgba(0,0,0,0.35)';
551:     ctx.lineWidth = 1.4;
552:     ctx.stroke();
553:     // heading
554:     const sp = Math.hypot(c.vx, c.vy);
555:     if (sp > 0.5) {
556:       ctx.strokeStyle = `hsla(${d.hue}, 72%, 56%, 0.85)`;
557:       ctx.lineWidth = 2;
558:       ctx.beginPath();
559:       ctx.moveTo(sx, sy);
560:       ctx.lineTo(sx + (c.vx / sp) * r * 1.4, sy + (c.vy / sp) * r * 1.4);
561:       ctx.stroke();
562:     }
563:     // energy bar above head
564:     const bw = r * 2.4, bh = 4;
565:     ctx.fillStyle = energyPct > 0.6 ? '#6ee7b7' : energyPct > 0.3 ? '#fbbf24' : '#f87171';
566:     ctx.fillRect(sx - bw / 2, sy - r - 9, bw * energyPct, bh);
567:     ctx.strokeStyle = 'rgba(0,0,0,0.45)';
568:     ctx.strokeRect(sx - bw / 2, sy - r - 9, bw, bh);
569:     // selection halo
570:     if (selectedId === c.id) {
571:       ctx.strokeStyle = '#fff';
572:       ctx.lineWidth = 2.2;
573:       ctx.beginPath();
574:       ctx.arc(sx, sy, r + 5, 0, Math.PI * 2);
575:       ctx.stroke();
576:     }
577:     ctx.globalAlpha = 1;
578:   }
579: }
