import { createRequire } from 'node:module'
import { mkdirSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire(join('/tmp/opencode/package.json', 'package.json'))
const { chromium } = require('playwright-core')

const url = 'http://localhost:3002/'
const output = '/tmp/opencode/screenshots'
mkdirSync(output, { recursive: true })

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
})

for (const [name, width, height] of [
  ['desktop', 1440, 900],
  ['mobile', 390, 844],
]) {
  const page = await browser.newPage({ viewport: { width, height } })
  page.setDefaultTimeout(30000)
  const errors = []
  page.on('pageerror', (e) => errors.push(e.message))
  page.on('response', (r) => {
    if (r.status() >= 400 && new URL(r.url()).origin === new URL(url).origin) errors.push(`HTTP ${r.status()}: ${r.url()}`)
  })
  await page.goto(url, { waitUntil: 'load', timeout: 45000 })
  await page.locator('#app .shell').waitFor({ state: 'visible', timeout: 30000 })
  await page.locator('.stage-head h1').waitFor({ state: 'visible', timeout: 30000 })
  await page.waitForFunction(() => document.fonts.status === 'loaded', null, { timeout: 30000 })
  await page.waitForTimeout(1500)
  await page.screenshot({ path: join(output, `final-${name}.png`), fullPage: false, timeout: 30000 })
  console.log(`Captured ${name}: errors=${errors.length}`, errors.slice(0, 3).join('; '))
  await page.close()
}
await browser.close()
console.log('done')

