  const parents = []
  let e = rc
  while (e && e !== document.body) { parents.push(e.tagName + (e.className?'.'+e.className.slice(0,20):'') + '#'+e.id); e = e.parentElement }
  return {
    habitatNav: gs('.habitat-nav'),
