import { createRequire } from 'node:module'
const require = createRequire('/tmp/opencode/package.json')
const { chromium } = require('playwright-core')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-gpu'] })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 })
await page.waitForTimeout(1500)
// Remove pointer-events:none from workspace to test
await page.evaluate(() => { document.querySelector('.workspace').style.pointerEvents = 'auto' })
const res = await page.evaluate(() => {
  const b = document.querySelector('.habitat-nav [data-nav="up"]')
  const r = b.getBoundingClientRect()
  const top = document.elementFromPoint(Math.round(r.left+r.width/2), Math.round(r.top+r.height/2))
  return { topCls: top?top.className:'', topTag: top?top.tagName:'', x:Math.round(r.left+r.width/2), y:Math.round(r.top+r.height/2) }
})
console.log('after workspace pointer-events=auto:', JSON.stringify(res))
await browser.close()

import { createRequire } from 'node:module'
const require = createRequire('/tmp/opencode/package.json')
const { chromium } = require('playwright-core')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-gpu'] })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 })
await page.waitForTimeout(1500)
// Move habitat-nav to body root, give high z-index
await page.evaluate(() => {
  const nav = document.querySelector('.habitat-nav')
  nav.style.zIndex = '50'
  document.body.appendChild(nav)
})
const res = await page.evaluate(() => {
  const check = (sel) => {
    const b = document.querySelector('.habitat-nav [data-nav="'+sel+'"]')
    if(!b) return {sel, found:false}
    const r = b.getBoundingClientRect()
    const top = document.elementFromPoint(Math.round(r.left+r.width/2), Math.round(r.top+r.height/2))
    return {sel, x:Math.round(r.left+r.width/2), y:Math.round(r.top+r.height/2), topTag: top?top.tagName:'', topCls: top?top.className:'', topDataNav: top?(top.dataset.nav||top.dataset.zoom||''):''}
  }
  return ['up','down','left','right','in','out','reset'].map(check)
})
console.log(JSON.stringify(res, null, 2))
await browser.close()

