import { createRequire } from 'node:module'
const require = createRequire('/tmp/opencode/package.json')
const { chromium } = require('playwright-core')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-gpu'] })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
page.on('console', (m) => { if (m.type() === 'error') errors.push('console:' + m.text()) })
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 })
await page.waitForTimeout(1500)
// 1) stacking: each nav button must be the topmost at its center
const stack = await page.evaluate(() => {
  const out = []
  for (const b of [...document.querySelectorAll('.habitat-nav button')]) {
    const r = b.getBoundingClientRect()
    const top = document.elementFromPoint(Math.round(r.left + r.width / 2), Math.round(r.top + r.height / 2))
    out.push({ sel: b.dataset.nav || b.dataset.zoom, x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2), topTag: top ? top.tagName : '', topData: top ? (top.dataset.nav || top.dataset.zoom || '') : '' })
  }
  return out
})
console.log('STACKING:'); for (const s of stack) console.log('  ', JSON.stringify(s))
// 2) click every nav button, ensure no errors
for (const sel of ['up','down','left','right','in','out','reset']) {
  await page.locator('.habitat-nav [data-nav="'+sel+'"], .habitat-nav [data-zoom="'+sel+'"]').first().click()
  await page.waitForTimeout(80)
}
console.log('JS errors after clicks:', errors.length, errors.slice(0,4).join(' | '))
await page.screenshot({ path: '/tmp/opencode/screenshots/final-mobile.png', fullPage: false })
await browser.close()
console.log('done')

